contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept a payment amount and an initial setup flag that can optionally make a prior ticket purchase
    // so pot might be nonzero. amount should be the Ether forwarded to c.play.
    function run(uint amount, bool doPrior) public payable {
        require(address(this).balance >= amount);
        // Optionally make a prior purchase to set a nonzero pot
        if (doPrior) {
            // send exactly TICKET_AMOUNT for prior purchase
            // Use c.play{value: amountPrior}(); but we must ensure amountPrior equals C.TICKET_AMOUNT (10)
            // We cannot read constants from C directly besides public getters; so we hardcode expected ticket amount (10) here as input-independent setup
            // To satisfy constraints we will only do prior when caller provides >=10 and uses 10
            require(address(this).balance >= 10);
            c.play{value: 10}();
        }

        // Read balances and pot before the decisive call
        uint potBefore = c.pot();
        uint bankBalanceBefore = address(c.bank()).balance; // bank() is public
        uint contractBalanceBefore = address(c).balance;
        uint selfBalanceBefore = address(this).balance;

        bool reverted;
        // Call play with the provided amount; catch revert
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint potAfter = c.pot();
        uint bankBalanceAfter = address(c.bank()).balance;
        uint contractBalanceAfter = address(c).balance;
        uint selfBalanceAfter = address(this).balance;

        // General rule asserts behavior for the exact ticket amount case.
        // If the call reverted, then it must be because amount != TICKET_AMOUNT (10), so require that amount != 10.
        // If the call did not revert and amount == 10 then exactly one of two outcomes holds:
        // 1) payout branch executed: potAfter == 0 AND bank gained FEE_AMOUNT (1) AND caller (this) gained (potBefore + 10 - 1)
        // 2) payout branch did not execute: potAfter == potBefore + 10 AND balances otherwise reflect that (contract balance increased by 10)

        assert(
            // If reverted then amount != 10
            (reverted && amount != 10)
            ||
            // If not reverted then amount == 10 and one of the two described outcomes holds
            (!reverted && amount == 10 && (
                // outcome A: payout branch executed
                (
                    potAfter == 0
                    && bankBalanceAfter == bankBalanceBefore + 1
                    && selfBalanceAfter == selfBalanceBefore + (potBefore + 10 - 1)
                    && contractBalanceAfter == contractBalanceBefore - (potBefore + 10 - 1) - 1
                )
                ||
                // outcome B: payout branch did not execute
                (
                    potAfter == potBefore + 10
                    && contractBalanceAfter == contractBalanceBefore + 10
                    && bankBalanceAfter == bankBalanceBefore
                    && selfBalanceAfter == selfBalanceBefore - 10
                )
            ))
        );
    }

    // receive to be able to accept refunds/transfers
    receive() external payable {}
}

