contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: send an arbitrary ticketAmount to c via play
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // read observable state before the call
        address bankBefore = c.bank();
        uint potBefore = c.pot();
        uint balBefore = address(c).balance;

        // perform the call and record whether it reverted
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable state after the call
        address bankAfter = c.bank();
        uint potAfter = c.pot();
        uint balAfter = address(c).balance;

        // General rule:
        // - bank address never changes
        // - if the call reverted then nothing on c changed (pot and balance unchanged)
        // - if the call did not revert then amount must equal TICKET_AMOUNT, and either
        //   (A) pot increased exactly by amount (no payout case), or
        //   (B) pot became 0 and contract balance decreased by FEE_AMOUNT (payout case)
        // We express constants via observable differences to avoid redeclaring them.

        assert(
            // bank immutable
            bankBefore == bankAfter
            && (
                reverted
                ? (potBefore == potAfter && balBefore == balAfter)
                : (
                    // on success, amount must have been the required ticket amount: balance increased by amount then possibly decreased by payout
                    // We can't read TICKET_AMOUNT constant, but we can require that the caller sent exactly the delta seen on c before the payout
                    // Two possibilities: no payout (pot increases by amount and contract balance increases by amount)
                    (potAfter == potBefore + amount && balAfter == balBefore + amount)
                    // or payout happened: pot becomes 0 and contract balance decreased by FEE_AMOUNT compared to potBefore+amount
                    || (potAfter == 0 && balAfter + (potBefore + amount - balAfter) == balBefore + amount)
                  )
            )
        );
    }

    // receive to accept refunds/ether if needed
    receive() external payable {}
}

