contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept two inputs: the amount of Ether to send when calling play, and a dummy address to help observe balances
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to forward");

        // read before-values
        address bankBefore = c.bank();
        uint potBefore = c.pot();
        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;

        bool reverted;
        // Attempt to call play with provided amount
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        address bankAfter = c.bank();
        uint potAfter = c.pot();
        uint cBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;

        // General rule expressed as one assert:
        // - bank address never changes
        // - If amount != TICKET_AMOUNT then call must revert and state/balances unchanged
        // - If amount == TICKET_AMOUNT then call must not revert; exactly one of two outcomes holds:
        //    * random == 0 branch: potAfter == 0 and c balance decreased by potBefore + amount and this contract balance increased by potBefore + amount - FEE_AMOUNT (but we cannot refer to internal random; we check observable invariants)
        //    * random == 1 branch: potAfter == potBefore + amount and c balance increased by amount
        // Because we cannot name constants from C here, we express relations using observed values only.

        assert(
            bankBefore == bankAfter && (
                // case: payment was not correct -> revert and nothing changed
                (amount != 10 && reverted && potAfter == potBefore && cBalAfter == cBalBefore && thisBalAfter == thisBalBefore)
                ||
                // case: correct payment -> must not revert and either pot reset to 0 and c balance decreased appropriately,
                // or pot increased by amount and c balance increased by amount
                (amount == 10 && !reverted && (
                    (potAfter == 0 && cBalAfter + potBefore + amount == cBalBefore + potBefore + amount && thisBalAfter >= thisBalBefore)
                    ||
                    (potAfter == potBefore + amount && cBalAfter == cBalBefore + amount)
                ))
            )
        );
    }

    // allow contract to receive Ether so we can fund calls
    receive() external payable {}
}

